# ! [doc = " Utilities related to FFI bindings."] # ! [doc = ""] # ! [doc = " This module provides utilities to handle data across non-Rust"] # ! [doc = " interfaces, like other programming languages and the underlying"] # ! [doc = " operating system. It is mainly of use for FFI (Foreign Function"] # ! [doc = " Interface) bindings and code that needs to exchange C-like strings"] # ! [doc = " with other languages."] # ! [doc = ""] # ! [doc = " # Overview"] # ! [doc = ""] # ! [doc = " Rust represents owned strings with the [`String`] type, and"] # ! [doc = " borrowed slices of strings with the [`str`] primitive. Both are"] # ! [doc = " always in UTF-8 encoding, and may contain nul bytes in the middle,"] # ! [doc = " i.e., if you look at the bytes that make up the string, there may"] # ! [doc = " be a `\\0` among them. Both `String` and `str` store their length"] # ! [doc = " explicitly; there are no nul terminators at the end of strings"] # ! [doc = " like in C."] # ! [doc = ""] # ! [doc = " C strings are different from Rust strings:"] # ! [doc = ""] # ! [doc = " * **Encodings** - Rust strings are UTF-8, but C strings may use"] # ! [doc = " other encodings. If you are using a string from C, you should"] # ! [doc = " check its encoding explicitly, rather than just assuming that it"] # ! [doc = " is UTF-8 like you can do in Rust."] # ! [doc = ""] # ! [doc = " * **Character size** - C strings may use `char` or `wchar_t`-sized"] # ! [doc = " characters; please **note** that C's `char` is different from Rust's."] # ! [doc = " The C standard leaves the actual sizes of those types open to"] # ! [doc = " interpretation, but defines different APIs for strings made up of"] # ! [doc = " each character type. Rust strings are always UTF-8, so different"] # ! [doc = " Unicode characters will be encoded in a variable number of bytes"] # ! [doc = " each. The Rust type [`char`] represents a '[Unicode scalar"] # ! [doc = " value]', which is similar to, but not the same as, a '[Unicode"] # ! [doc = " code point]'."] # ! [doc = ""] # ! [doc = " * **Nul terminators and implicit string lengths** - Often, C"] # ! [doc = " strings are nul-terminated, i.e., they have a `\\0` character at the"] # ! [doc = " end. The length of a string buffer is not stored, but has to be"] # ! [doc = " calculated; to compute the length of a string, C code must"] # ! [doc = " manually call a function like `strlen()` for `char`-based strings,"] # ! [doc = " or `wcslen()` for `wchar_t`-based ones. Those functions return"] # ! [doc = " the number of characters in the string excluding the nul"] # ! [doc = " terminator, so the buffer length is really `len+1` characters."] # ! [doc = " Rust strings don't have a nul terminator; their length is always"] # ! [doc = " stored and does not need to be calculated. While in Rust"] # ! [doc = " accessing a string's length is an *O*(1) operation (because the"] # ! [doc = " length is stored); in C it is an *O*(*n*) operation because the"] # ! [doc = " length needs to be computed by scanning the string for the nul"] # ! [doc = " terminator."] # ! [doc = ""] # ! [doc = " * **Internal nul characters** - When C strings have a nul"] # ! [doc = " terminator character, this usually means that they cannot have nul"] # ! [doc = " characters in the middle — a nul character would essentially"] # ! [doc = " truncate the string. Rust strings *can* have nul characters in"] # ! [doc = " the middle, because nul does not have to mark the end of the"] # ! [doc = " string in Rust."] # ! [doc = ""] # ! [doc = " # Representations of non-Rust strings"] # ! [doc = ""] # ! [doc = " [`CString`] and [`CStr`] are useful when you need to transfer"] # ! [doc = " UTF-8 strings to and from languages with a C ABI, like Python."] # ! [doc = ""] # ! [doc = " * **From Rust to C:** [`CString`] represents an owned, C-friendly"] # ! [doc = " string: it is nul-terminated, and has no internal nul characters."] # ! [doc = " Rust code can create a [`CString`] out of a normal string (provided"] # ! [doc = " that the string doesn't have nul characters in the middle), and"] # ! [doc = " then use a variety of methods to obtain a raw <code>\\*mut [u8]</code> that can"] # ! [doc = " then be passed as an argument to functions which use the C"] # ! [doc = " conventions for strings."] # ! [doc = ""] # ! [doc = " * **From C to Rust:** [`CStr`] represents a borrowed C string; it"] # ! [doc = " is what you would use to wrap a raw <code>\\*const [u8]</code> that you got from"] # ! [doc = " a C function. A [`CStr`] is guaranteed to be a nul-terminated array"] # ! [doc = " of bytes. Once you have a [`CStr`], you can convert it to a Rust"] # ! [doc = " <code>&[str]</code> if it's valid UTF-8, or lossily convert it by adding"] # ! [doc = " replacement characters."] # ! [doc = ""] # ! [doc = " [`String`]: crate::string::String"] # ! [doc = " [`CStr`]: core::ffi::CStr"] # ! [stable (feature = "alloc_ffi" , since = "1.64.0")] use split_decls_genesis :: ourprelude :: * ; #[doc (inline)] #[stable (feature = "alloc_c_string" , since = "1.64.0")] pub use self :: c_str :: CString ; #[doc (inline)] #[stable (feature = "alloc_c_string" , since = "1.64.0")] pub use self :: c_str :: { FromVecWithNulError , IntoStringError , NulError } ; #[stable (feature = "c_str_module" , since = "1.88.0")] pub mod c_str ;